UPDATE utb_office_employee
SET    del_yn = 'N', acct_status_code = 'ACTIVE',
       update_at = CURRENT_TIMESTAMP, update_user = #{userMstSeq}
WHERE  office_seq = #{officeSeq} AND user_mst_seq = #{userMstSeq}

UPDATE utb_office_employee
SET    del_yn = 'Y', update_at = CURRENT_TIMESTAMP, update_user = #{userMstSeq}
WHERE  user_mst_seq = #{userMstSeq} AND del_yn = 'N'

UPDATE utb_office_mst
SET    del_yn = 'Y', update_at = CURRENT_TIMESTAMP, update_user = #{userMstSeq}
WHERE  office_seq IN (
    SELECT oe.office_seq FROM utb_office_employee oe
    INNER JOIN utb_office_mst o ON oe.office_seq = o.office_seq
    WHERE  oe.user_mst_seq = #{userMstSeq}
      AND  o.office_auth_yn = 'N'
      AND  o.office_seq LIKE 'USRKR%'
      AND  oe.admin_auth = 'Y'
)

